            aug[col] = aug[maxRow];
            aug[maxRow] = temp;
        }

        // Eliminate
        for (var row = col + 1; row < n; row += 1)
        {
            var factor = aug[row][col] / aug[col][col];
            for (var j = col; j <= n; j += 1)
            {
                aug[row][j] = aug[row][j] - factor * aug[col][j];
            }
        }
    }

