    var x = [];
    for (var i = 0; i < n; i += 1)
    {
        x = append(x, 0);
    }

    for (var i = n - 1; i >= 0; i -= 1)
    {
        var sum = aug[i][n];
        for (var j = i + 1; j < n; j += 1)
        {
            sum = sum - aug[i][j] * x[j];
        }
        x[i] = sum / aug[i][i];
    }

    return x;
}

